DROP DATABASE IF EXISTS school_hub;
CREATE DATABASE school_hub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE school_hub;
CREATE TABLE utenti(id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(100) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,ruolo ENUM('studente','professore','genitore','admin') NOT NULL,classe VARCHAR(20) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE materie(id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(80) NOT NULL,professore_id INT NULL,CONSTRAINT fk_mat_prof FOREIGN KEY(professore_id) REFERENCES utenti(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE presenze(id INT AUTO_INCREMENT PRIMARY KEY,studente_id INT NOT NULL,materia_id INT NULL,data DATE NOT NULL,stato ENUM('presente','assente','giustificato') NOT NULL,note VARCHAR(255) NULL,FOREIGN KEY(studente_id) REFERENCES utenti(id) ON DELETE CASCADE,FOREIGN KEY(materia_id) REFERENCES materie(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE voti(id INT AUTO_INCREMENT PRIMARY KEY,studente_id INT NOT NULL,materia_id INT NOT NULL,voto DECIMAL(3,1) NOT NULL,tipo VARCHAR(50) NOT NULL,data DATE NOT NULL,FOREIGN KEY(studente_id) REFERENCES utenti(id) ON DELETE CASCADE,FOREIGN KEY(materia_id) REFERENCES materie(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE orario(id INT AUTO_INCREMENT PRIMARY KEY,classe VARCHAR(20) NOT NULL,materia_id INT NOT NULL,giorno_settimana TINYINT NOT NULL,ora_inizio TIME NOT NULL,ora_fine TIME NOT NULL,FOREIGN KEY(materia_id) REFERENCES materie(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE verifiche(id INT AUTO_INCREMENT PRIMARY KEY,classe VARCHAR(20) NOT NULL,materia_id INT NOT NULL,descrizione VARCHAR(200) NOT NULL,data DATE NOT NULL,FOREIGN KEY(materia_id) REFERENCES materie(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE messaggi(id INT AUTO_INCREMENT PRIMARY KEY,mittente_id INT NULL,destinatario_id INT NOT NULL,oggetto VARCHAR(150) NOT NULL,corpo TEXT,letto TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(mittente_id) REFERENCES utenti(id) ON DELETE SET NULL,FOREIGN KEY(destinatario_id) REFERENCES utenti(id) ON DELETE CASCADE) ENGINE=InnoDB;